SELECT COUNT(*) > 0
FROM SETTLEMENT
WHERE job_id = #{jobId}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}

SELECT COUNT(*) > 0
FROM SETTLEMENT
WHERE user_id = #{userId}
  AND status = #{status}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}

SELECT *
FROM SETTLEMENT
WHERE user_id = #{userId}
  AND deposit_date BETWEEN #{startDate} AND #{endDate}
